-- Tables never analyzed (made just now, or too small for autovacuum to have reached them) are planned
-- as ten pages of rows: a table of 6 rows as thousands. Through the rules' lookups that becomes an estimate of
-- hundreds of thousands, and Postgres compiles (JIT) and plans for reads of a few rows. ANALYZE reads a
-- sample (30,000 rows at most) and blocks neither reads nor writes.
DO $an$
DECLARE r record;
BEGIN
  FOR r IN SELECT c.oid::regclass AS tbl FROM pg_class c
           WHERE c.relkind = 'r' AND c.relpersistence <> 't' AND c.reltuples < 0
             AND pg_has_role(c.relowner, 'USAGE')
             AND (c.relnamespace IN (SELECT oid FROM pg_namespace WHERE nspname IN ('authz', 'authz_int'))
                  OR c.oid = ANY (SELECT to_regclass(x) FROM unnest(ARRAY['"app"."users"', '"app"."services"', '"app"."projects"', '"app"."members"', '"app"."project_services"', '"app"."notes"', '"app"."inbox"', '"app"."feedback"', '"app"."folders"']::text[]) x)) LOOP
    EXECUTE format('ANALYZE %s', r.tbl);
  END LOOP;
END $an$;

DROP SCHEMA IF EXISTS authz_keep CASCADE;
DO $authz_built$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM authz_int.next_trees) THEN DROP TABLE authz_int.next_trees; END IF;
END $authz_built$;

-- the policy now in force
INSERT INTO authz.policy_versions (action, policy, files, version, lock)
VALUES ('apply', $authz_policy$-- The conformance app's policy (integrations/fastapi's, over integer keys, with viewers people share projects with,
-- and feedback): projects with an owner and members, public ones anyone may read, a service that reads the
-- projects it is added to, notes in projects, an inbox only its recipient reads, feedback on a project only its
-- owner reads, and folders inside folders, which their owner and the owners of the folders above edit.

app role conf_app

type user = app.users(id integer)

type service = app.services(id integer) principal

type project = app.projects(id integer)
  owner   : user    = owner_id
  member  : user    = app.members(project_id -> user_id)
  service : service = app.project_services(project_id -> service_id)
  viewer  : user shared by edit

  can edit  = owner or member
  can view  = edit or service or viewer or {public}
  can share = owner

type note = app.notes(id integer)
  project : project = project_id
  author  : user    = author_id

  can edit = author or project.owner
  can view = project.view

type message = app.inbox(id integer)
  recipient : user = recipient_id

  can read = recipient

type feedback = app.feedback(id integer)
  project : project = project_id
  author  : user    = author_id

  can read = project.owner

type folder = app.folders(id integer)
  parent : folder = parent_id
  owner  : user   = owner_id

  can edit = owner or parent.edit

rules app.projects
  select : view

rules app.notes
  select : view
  insert : project.edit and author
  update : edit
  delete : edit

rules app.inbox
  select : read
  insert : signed_in and {sender_id = authz.uid()}

rules app.feedback
  select : read
  insert : project.view and author

rules app.folders
  select : edit
  update : edit
$authz_policy$,
  $authz_files${}$authz_files$::jsonb, '0.1.0-dev+24a3c0cc8021', '4e34576d682f08b7');
